:root{
  --bg:#0d1117;--surface:#151b23;--surface2:#1c2129;--surface3:#232932;
  --border:rgba(240,246,252,0.08);--border2:rgba(240,246,252,0.14);
  --text:#e6edf3;--text-muted:#7d8590;--text-dim:#9ea7b3;
  --accent:#2f81f7;--accent-dim:rgba(47,129,247,0.14);--accent-glow:rgba(47,129,247,0.25);
  --green:#3fb950;--green-dim:rgba(63,185,80,0.12);
  --amber:#d29922;--amber-dim:rgba(210,153,34,0.12);
  --red:#f85149;--red-dim:rgba(248,81,73,0.12);
  --teal:#39c5cf;--teal-dim:rgba(57,197,207,0.12);
  --orange:#db6d28;--purple:#a371f7;--purple-dim:rgba(163,113,247,0.12);
  --font:'Inter',sans-serif;--mono:'JetBrains Mono',monospace;
  --radius-sm:6px;--radius-md:8px;--radius-lg:12px;--radius-xl:16px;
  --shadow-sm:0 1px 2px rgba(1,4,9,0.5);
  --shadow-md:0 3px 12px rgba(1,4,9,0.55);
  --shadow-lg:0 8px 28px rgba(1,4,9,0.6);
  --transition:all 0.15s cubic-bezier(.4,0,.2,1);
  --theme-bg-image:none;
}
html.light{
  --bg:#f0f4f8;--surface:#ffffff;--surface2:#f8fafc;--surface3:#e8eef4;
  --border:rgba(0,0,0,0.08);--border2:rgba(0,0,0,0.14);
  --text:#0f172a;--text-muted:#64748b;--text-dim:#475569;
  --accent:#2563eb;--accent-dim:rgba(37,99,235,0.1);--accent-glow:rgba(37,99,235,0.2);
  --green:#16a34a;--green-dim:rgba(22,163,74,0.1);
  --amber:#d97706;--amber-dim:rgba(217,119,6,0.1);
  --red:#dc2626;--red-dim:rgba(220,38,38,0.1);
  --teal:#0d9488;--teal-dim:rgba(13,148,136,0.1);
  --orange:#ea580c;--purple:#9333ea;--purple-dim:rgba(147,51,234,0.1);
}
/* ── Newfold Digital Philippines theme ─────────────────────────────────────── */
html.newfold{
  --bg:#0f1117;--surface:#181c25;--surface2:#1e2330;--surface3:#252c3a;
  --border:rgba(249,115,22,0.09);--border2:rgba(249,115,22,0.18);
  --text:#f1f2f4;--text-muted:#7a8394;--text-dim:#a0aab8;
  --accent:#f97316;--accent-dim:rgba(249,115,22,0.14);--accent-glow:rgba(249,115,22,0.28);
  --green:#22c55e;--green-dim:rgba(34,197,94,0.12);
  --amber:#f59e0b;--amber-dim:rgba(245,158,11,0.12);
  --red:#ef4444;--red-dim:rgba(239,68,68,0.12);
  --teal:#14b8a6;--teal-dim:rgba(20,184,166,0.12);
  --orange:#f97316;--purple:#a855f7;--purple-dim:rgba(168,85,247,0.12);
}
html.newfold .nav-item.active{background:rgba(249,115,22,0.13);color:#f97316;}
html.newfold .nav-item.active::before{background:#f97316;}
html.newfold .sidebar{border-right-color:rgba(249,115,22,0.12);}
html.newfold .sidebar-logo-icon{background:linear-gradient(135deg,#c2410c,#f97316);}
html.newfold .new-period-btn{background:rgba(249,115,22,0.12);border-color:rgba(249,115,22,0.3);color:#f97316;}
html.newfold .new-period-btn:hover{background:rgba(249,115,22,0.22);}
html.newfold .period-selects select:focus{border-color:#f97316;}

/* ── Nature / Forest theme (earth greens, warm soil) ─────────────────────── */
html.nature{
  --bg:#0b1209;--surface:#111a0e;--surface2:#172214;--surface3:#1d2b19;
  --border:rgba(74,222,128,0.08);--border2:rgba(74,222,128,0.18);
  --text:#e8f5e2;--text-muted:#6b7f65;--text-dim:#98b090;
  --accent:#4ade80;--accent-dim:rgba(74,222,128,0.13);--accent-glow:rgba(74,222,128,0.28);
  --green:#86efac;--green-dim:rgba(134,239,172,0.12);
  --amber:#fcd34d;--amber-dim:rgba(252,211,77,0.12);
  --red:#f87171;--red-dim:rgba(248,113,113,0.12);
  --teal:#5eead4;--teal-dim:rgba(94,234,212,0.12);
  --orange:#fdba74;--purple:#c4b5fd;--purple-dim:rgba(196,181,253,0.12);
}
html.nature .sidebar-logo-icon{background:linear-gradient(135deg,#166534,#4ade80);}
html.nature .nav-item.active{background:rgba(74,222,128,0.12);color:#4ade80;}
html.nature .nav-item.active::before{background:linear-gradient(180deg,#4ade80,#86efac);}
html.nature .sidebar{border-right-color:rgba(74,222,128,0.1);}
html.nature .new-period-btn{background:rgba(74,222,128,0.11);border-color:rgba(74,222,128,0.3);color:#4ade80;}
html.nature .new-period-btn:hover{background:rgba(74,222,128,0.2);}
html.nature .period-selects select:focus{border-color:#4ade80;}
html.nature .section-title::before{background:linear-gradient(180deg,#4ade80,#5eead4);}
html.nature .kpi-card:hover{box-shadow:0 4px 20px rgba(74,222,128,0.18);}

/* ── Galaxy / Cosmos theme (deep space, star blues) ──────────────────────── */
html.galaxy{
  --bg:#03050f;--surface:#080d1e;--surface2:#0e1530;--surface3:#141d3e;
  --border:rgba(96,165,250,0.09);--border2:rgba(96,165,250,0.2);
  --text:#dce8ff;--text-muted:#5a6e99;--text-dim:#8da0c9;
  --accent:#60a5fa;--accent-dim:rgba(96,165,250,0.14);--accent-glow:rgba(96,165,250,0.3);
  --green:#6ee7b7;--green-dim:rgba(110,231,183,0.12);
  --amber:#fde68a;--amber-dim:rgba(253,230,138,0.12);
  --red:#fca5a5;--red-dim:rgba(252,165,165,0.12);
  --teal:#67e8f9;--teal-dim:rgba(103,232,249,0.12);
  --orange:#fdba74;--purple:#c4b5fd;--purple-dim:rgba(196,181,253,0.15);
}
html.galaxy .sidebar-logo-icon{background:linear-gradient(135deg,#1e3a8a,#7c3aed);}
html.galaxy .nav-item.active{background:rgba(96,165,250,0.12);color:#60a5fa;}
html.galaxy .nav-item.active::before{background:linear-gradient(180deg,#60a5fa,#c4b5fd);}
html.galaxy .sidebar{border-right-color:rgba(96,165,250,0.1);}
html.galaxy .new-period-btn{background:rgba(96,165,250,0.11);border-color:rgba(96,165,250,0.3);color:#60a5fa;}
html.galaxy .new-period-btn:hover{background:rgba(96,165,250,0.2);}
html.galaxy .period-selects select:focus{border-color:#60a5fa;}
html.galaxy .section-title::before{background:linear-gradient(180deg,#60a5fa,#c4b5fd);}
html.galaxy .kpi-card:hover{box-shadow:0 4px 24px rgba(96,165,250,0.2);}
html.galaxy body::before{content:'';position:fixed;inset:0;pointer-events:none;z-index:0;
  background:radial-gradient(ellipse at 20% 15%,rgba(96,165,250,0.04) 0%,transparent 50%),
             radial-gradient(ellipse at 80% 80%,rgba(196,181,253,0.04) 0%,transparent 50%);}

/* ── Positive Thinking / Sunrise theme (warm gold, white light) ───────────── */
html.sunrise{
  --bg:#fffbf0;--surface:#ffffff;--surface2:#fef9e8;--surface3:#fef3c7;
  --border:rgba(245,158,11,0.12);--border2:rgba(245,158,11,0.25);
  --text:#1c1407;--text-muted:#92714a;--text-dim:#5c4a2a;
  --accent:#d97706;--accent-dim:rgba(217,119,6,0.12);--accent-glow:rgba(217,119,6,0.25);
  --green:#059669;--green-dim:rgba(5,150,105,0.1);
  --amber:#b45309;--amber-dim:rgba(180,83,9,0.1);
  --red:#dc2626;--red-dim:rgba(220,38,38,0.1);
  --teal:#0d9488;--teal-dim:rgba(13,148,136,0.1);
  --orange:#ea580c;--purple:#7c3aed;--purple-dim:rgba(124,58,237,0.1);
}
html.sunrise .sidebar-logo-icon{background:linear-gradient(135deg,#f59e0b,#f97316);}
html.sunrise .nav-item.active{background:rgba(217,119,6,0.12);color:#d97706;}
html.sunrise .nav-item.active::before{background:linear-gradient(180deg,#f59e0b,#f97316);}
html.sunrise .sidebar{border-right-color:rgba(245,158,11,0.15);}
html.sunrise .new-period-btn{background:rgba(217,119,6,0.1);border-color:rgba(217,119,6,0.3);color:#d97706;}
html.sunrise .new-period-btn:hover{background:rgba(217,119,6,0.18);}
html.sunrise .period-selects select:focus{border-color:#d97706;}
html.sunrise .section-title::before{background:linear-gradient(180deg,#f59e0b,#f97316);}
html.sunrise .kpi-card:hover{box-shadow:0 4px 16px rgba(245,158,11,0.15);}
html.sunrise .sidebar{background:var(--surface);border-right:1px solid var(--border);}

/* ── Cyberpunk / Neon City (bonus) ───────────────────────────────────────── */
html.cyberpunk{
  --bg:#060812;--surface:#0c0f1e;--surface2:#121628;--surface3:#181e34;
  --border:rgba(0,255,200,0.08);--border2:rgba(0,255,200,0.2);
  --text:#d0ffe8;--text-muted:#3a6055;--text-dim:#5db89a;
  --accent:#00ffc8;--accent-dim:rgba(0,255,200,0.12);--accent-glow:rgba(0,255,200,0.3);
  --green:#00ffc8;--green-dim:rgba(0,255,200,0.12);
  --amber:#ffe600;--amber-dim:rgba(255,230,0,0.12);
  --red:#ff3860;--red-dim:rgba(255,56,96,0.12);
  --teal:#00e5ff;--teal-dim:rgba(0,229,255,0.12);
  --orange:#ff6e40;--purple:#d050ff;--purple-dim:rgba(208,80,255,0.15);
}
html.cyberpunk .sidebar-logo-icon{background:linear-gradient(135deg,#0a1628,#00ffc8);}
html.cyberpunk .nav-item.active{background:rgba(0,255,200,0.1);color:#00ffc8;}
html.cyberpunk .nav-item.active::before{background:linear-gradient(180deg,#00ffc8,#00e5ff);}
html.cyberpunk .sidebar{border-right-color:rgba(0,255,200,0.1);}
html.cyberpunk .new-period-btn{background:rgba(0,255,200,0.09);border-color:rgba(0,255,200,0.3);color:#00ffc8;}
html.cyberpunk .new-period-btn:hover{background:rgba(0,255,200,0.18);}
html.cyberpunk .period-selects select:focus{border-color:#00ffc8;}
html.cyberpunk .section-title::before{background:linear-gradient(180deg,#00ffc8,#d050ff);}
html.cyberpunk .kpi-card:hover{box-shadow:0 4px 24px rgba(0,255,200,0.2);}
html.cyberpunk .kpi-card::before{opacity:1;}

