  --amber:#fde68a;--amber-dim:rgba(253,230,138,0.12);
  --red:#fca5a5;--red-dim:rgba(252,165,165,0.12);
  --teal:#22d3ee;--teal-dim:rgba(34,211,238,0.14);
  --orange:#fdba74;--purple:#a78bfa;--purple-dim:rgba(167,139,250,0.12);
