html.ocean .sidebar-logo-icon{background:linear-gradient(135deg,#0e4d6e,#06b6d4);}
html.ocean .nav-item.active{background:rgba(6,182,212,0.12);color:#06b6d4;}
html.ocean .nav-item.active::before{background:linear-gradient(180deg,#06b6d4,#22d3ee);}
html.ocean .sidebar{border-right-color:rgba(6,182,212,0.1);}
html.ocean .new-period-btn{background:rgba(6,182,212,0.11);border-color:rgba(6,182,212,0.3);color:#06b6d4;}
