html.ocean .section-title::before{background:linear-gradient(180deg,#06b6d4,#22d3ee);}
html.ocean .kpi-card:hover{box-shadow:0 4px 20px rgba(6,182,212,0.2);}

/* ── Image-based themes ──────────────────────────────────────────────────── */
html.img-nature{
  --bg:#0b140d;--surface:rgba(15,26,17,0.92);--surface2:rgba(20,36,22,0.9);--surface3:rgba(25,44,28,0.88);
  --border:rgba(74,222,128,0.12);--border2:rgba(74,222,128,0.22);
  --text:#e8f5ea;--text-muted:#6b9e74;--text-dim:#8ab893;
  --accent:#4ade80;--accent-dim:rgba(74,222,128,0.15);--accent-glow:rgba(74,222,128,0.3);
  --theme-bg-image:url('https://images.unsplash.com/photo-1448375240586-882707db888b?w=1920&q=80');
  --theme-bg-overlay:rgba(5,18,8,0.62);
}
html.img-nature .sidebar,html.img-nature .kpi-card,html.img-nature .panel,html.img-nature .sum-card{backdrop-filter:blur(8px)}
html.img-nature .kpi-card:hover{box-shadow:0 4px 24px rgba(74,222,128,0.2);}
html.img-nature .section-title::before{background:linear-gradient(180deg,#4ade80,#16a34a);}
html.img-nature .period-selects select:focus{border-color:#4ade80;}

html.img-mountain{
