  --theme-bg-overlay:rgba(6,10,18,0.65);
}
html.img-mountain .sidebar,html.img-mountain .kpi-card,html.img-mountain .panel,html.img-mountain .sum-card{backdrop-filter:blur(8px)}
html.img-mountain .kpi-card:hover{box-shadow:0 4px 24px rgba(148,163,184,0.2);}
html.img-mountain .section-title::before{background:linear-gradient(180deg,#94a3b8,#475569);}
html.img-mountain .period-selects select:focus{border-color:#94a3b8;}

